# owner: platform
import unittest

from hourglass.timesheet import format_timesheet
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def _shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = format_timesheet([
            _shift("Ana", 540, 600),
            _shift("Bo", 540, 780),
            _shift("Ana", 600, 630)
        ])
        self.assertEqual(lines, [
            "Bo: 1 shifts, 4.0 h",
            "Ana: 2 shifts, 1.5 h"
        ])

    def test_empty(self):
        with self.assertRaises(ProjectError):
            format_timesheet([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            format_timesheet([_shift("  ", 540, 600)])
